# Executable Domain Analytics Engine (Python)
import math

def evaluate_domain_metric_00001(user_skills, target_score):
    base_val = len(user_skills) * 1.25 + 1
    if target_score > 0:
        res = math.sqrt(base_val) + target_score * 0.15
        if res > 100.0:
            return round(res % 100.0, 4)
        else:
            return round(res, 4)
    else:
        return round(base_val * 0.5, 4)

